//! `icon` and `file_icon`: Nerd Fonts glyphs by name, and by file.
//!
//! The tables in [`nerd`] and [`files`] are generated by `cargo xtask
//! gen-icons` from the upstream files vendored in `libbeachcomber/icons/`
//! (Nerd Fonts' `glyphnames.json`, nvim-web-devicons' two tables; both MIT).
//! The functions return code points only: colour is the template's.

mod files;
mod nerd;

use super::{UNDEFINED, arguments, is_absent, is_absent_text};
use crate::engine::{EngineCtx, op_error};
use minijinja::value::{Kwargs, Rest, Value as MjValue};
use minijinja::{Environment, Error};
use std::sync::Arc;

pub use nerd::VERSION;

pub(super) fn add_icon(env: &mut Environment<'_>, _: &Arc<EngineCtx>) {
    env.add_function(
        "icon",
        |args: Rest<MjValue>, kwargs: Kwargs| -> Result<MjValue, Error> {
            let [name] = arguments("icon", &args, &kwargs, ["name"])?;
            let name = name.unwrap_or(UNDEFINED);
            if is_absent(&name) {
                return Ok(UNDEFINED);
            }
            let Some(name) = name.as_str() else {
                return Err(op_error("icon(): name must be text"));
            };
            match glyph(name) {
                Some(c) => Ok(MjValue::from(c.to_string())),
                None => Err(op_error(format!(
                    "icon(): unknown glyph '{name}' (Nerd Fonts {VERSION})"
                ))),
            }
        },
    );
}

pub(super) fn add_file_icon(env: &mut Environment<'_>, _: &Arc<EngineCtx>) {
    env.add_function(
        "file_icon",
        |args: Rest<MjValue>, kwargs: Kwargs| -> Result<MjValue, Error> {
            let [path] = arguments("file_icon", &args, &kwargs, ["path"])?;
            let path = path.unwrap_or(UNDEFINED);
            if is_absent_text(&path) {
                return Ok(UNDEFINED);
            }
            let Some(path) = path.as_str() else {
                return Err(op_error("file_icon(): path must be text"));
            };
            Ok(MjValue::from(file_glyph(path).to_string()))
        },
    );
}

/// The Nerd Fonts glyph called `name` (`dev-git`, no `nf-`).
pub fn glyph(name: &str) -> Option<char> {
    let start = |i: usize| {
        if i == 0 {
            0
        } else {
            nerd::ENDS[i - 1] as usize
        }
    };
    let at = |i: usize| &nerd::NAMES[start(i)..nerd::ENDS[i] as usize];
    let (mut lo, mut hi) = (0, nerd::ENDS.len());
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match at(mid).cmp(name) {
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
            std::cmp::Ordering::Equal => return char::from_u32(nerd::CODES[mid]),
        }
    }
    None
}

/// The glyph for the file at `path`: by basename (exact, then lowercased), then
/// by extension (longest first, so `d.ts` before `ts`), else the default.
pub fn file_glyph(path: &str) -> char {
    let name = path.trim_end_matches('/').rsplit('/').next().unwrap_or("");
    let find = |table: &[(&str, char)], key: &str| {
        let get = |k: &str| {
            table
                .binary_search_by_key(&k, |e| e.0)
                .ok()
                .map(|i| table[i].1)
        };
        get(key).or_else(|| get(&key.to_lowercase()))
    };
    if let Some(c) = find(&files::BY_NAME, name) {
        return c;
    }
    // A leading dot starts the name (`.gitignore`), not an extension.
    let stem = name.trim_start_matches('.');
    for (i, _) in stem.match_indices('.') {
        if let Some(c) = find(&files::BY_EXT, &stem[i + 1..]) {
            return c;
        }
    }
    files::DEFAULT
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::library::testing::eval;

    fn ok(expr: &str) -> String {
        eval(expr).unwrap_or_else(|e| panic!("{expr}: {e}"))
    }

    #[test]
    fn icon_dev_git_is_u_e702() {
        assert_eq!(ok("icon('dev-git')"), "\u{e702}");
        assert_eq!(ok("icon('cod-account')"), "\u{eb99}");
        assert_eq!(
            ok("icon('oct-repo')"),
            glyph("oct-repo").unwrap().to_string()
        );
        // Astral code points work: md- glyphs live above U+FFFF.
        assert!(glyph("md-folder").unwrap() as u32 > 0xffff);
    }

    #[test]
    fn icon_unknown_is_an_error_naming_the_version() {
        let e = eval("icon('nope')").unwrap_err();
        assert!(
            e.contains(&format!(
                "icon(): unknown glyph 'nope' (Nerd Fonts {VERSION})"
            )),
            "{e}"
        );
        assert!(
            eval("icon('nf-dev-git')").is_err(),
            "one form: no nf- prefix"
        );
    }

    #[test]
    fn icon_absent_is_absent() {
        assert_eq!(ok("icon(none) is undefined"), "true");
        assert_eq!(ok("icon(missing) is undefined"), "true");
    }

    #[test]
    fn every_glyph_is_one_char() {
        assert!(nerd::CODES.iter().all(|&c| char::from_u32(c).is_some()));
        assert_eq!(nerd::CODES.len(), nerd::ENDS.len());
        assert_eq!(*nerd::ENDS.last().unwrap() as usize, nerd::NAMES.len());
    }

    #[test]
    fn names_are_sorted_and_unique() {
        let names: Vec<&str> = (0..nerd::ENDS.len())
            .map(|i| {
                let s = if i == 0 {
                    0
                } else {
                    nerd::ENDS[i - 1] as usize
                };
                &nerd::NAMES[s..nerd::ENDS[i] as usize]
            })
            .collect();
        assert!(names.windows(2).all(|w| w[0] < w[1]));
        assert!(glyph(names[names.len() / 2]).is_some());
    }

    #[test]
    fn file_icon_by_name() {
        assert_eq!(
            ok("file_icon('/a/b/.gitignore')"),
            files::BY_NAME[files::BY_NAME
                .binary_search_by_key(&".gitignore", |e| e.0)
                .unwrap()]
            .1
            .to_string()
        );
    }

    #[test]
    fn file_icon_by_lowercased_name() {
        assert_eq!(ok("file_icon('Makefile') == file_icon('makefile')"), "true");
        assert_ne!(file_glyph("Makefile"), files::DEFAULT);
    }

    #[test]
    fn file_icon_longest_extension_wins() {
        // `d.ts` and `ts` share a glyph upstream, so `test.ts` (different) proves the order.
        assert_eq!(file_glyph("x.test.ts"), '\u{f499}');
        assert_ne!(file_glyph("x.test.ts"), file_glyph("x.ts"));
        assert_eq!(file_glyph("src/main.rs"), file_glyph("a.rs"));
        assert_eq!(file_glyph("x.d.ts"), file_glyph("x.ts"));
    }

    #[test]
    fn file_icon_unknown_is_the_default() {
        assert_eq!(file_glyph("zzz.unheardof"), files::DEFAULT);
        assert_eq!(file_glyph(".nothing"), files::DEFAULT);
        assert_eq!(ok("file_icon('plain')"), files::DEFAULT.to_string());
        assert_eq!(files::DEFAULT, glyph("fa-file").unwrap());
    }

    #[test]
    fn file_icon_absent_is_absent() {
        assert_eq!(ok("file_icon(none) is undefined"), "true");
        assert_eq!(ok("file_icon('') is undefined"), "true");
    }

    #[test]
    fn file_icon_of_a_directory_path_uses_its_basename() {
        assert_eq!(file_glyph("/home/me/Makefile/"), file_glyph("Makefile"));
    }

    #[test]
    fn the_tables_are_sorted_for_binary_search() {
        assert!(files::BY_NAME.windows(2).all(|w| w[0].0 < w[1].0));
        assert!(files::BY_EXT.windows(2).all(|w| w[0].0 < w[1].0));
    }
}
